<?php
namespace App\Http\Controllers\Api\Referral;
use App\Http\Controllers\Controller; use App\Models\ReferralPartner; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException;
class PartnerAuthController extends Controller { public function register(){ $v=request()->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255','unique:referral_partners,email'],'phone'=>['nullable','string','max:50'],'password'=>['required','string','min:8','confirmed']]); $p=ReferralPartner::create([...$v,'email'=>strtolower(trim($v['email'])),'password'=>Hash::make($v['password']),'status'=>'active']); $token=$p->createToken('partner-web')->plainTextToken; return response()->json(['partner'=>$p->only(['id','name','email','phone','referral_code','status']),'token'=>$token],201); }
 public function login(){ $v=request()->validate(['email'=>['required','email'],'password'=>['required','string']]); $p=ReferralPartner::where('email',strtolower(trim($v['email'])))->first(); if(!$p||!$p->password||!Hash::check($v['password'],$p->password)||$p->status!=='active') throw ValidationException::withMessages(['email'=>['The referral partner credentials are incorrect or the account is inactive.']]); $p->tokens()->delete(); return response()->json(['partner'=>$p->only(['id','name','email','phone','referral_code','status']),'token'=>$p->createToken('partner-web')->plainTextToken]); }
 public function me(){ $p=request()->user(); abort_unless($p instanceof ReferralPartner, 403, 'Referral partner authentication required.'); return response()->json(['partner'=>$p->only(['id','name','email','phone','referral_code','status']),'referred_schools'=>$p->referredSchools()->select('id','name','is_active','created_at')->latest()->get(),'commissions'=>$p->commissions()->with('school:id,name')->latest()->get()]); }
 public function logout(){abort_unless(request()->user() instanceof ReferralPartner, 403, 'Referral partner authentication required.');request()->user()->currentAccessToken()?->delete();return response()->json(['message'=>'Signed out.']);}
}
